const now = new Date();

const formattedDate = now.toLocaleDateString('en-US', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

const dayOfWeek = now.toLocaleDateString('en-US', { weekday: 'long' });
const isoDate = now.toISOString().split('T')[0];

return {
  json: {
    date_formatted: formattedDate,
    day_of_week: dayOfWeek,
    iso_date: isoDate,
    timestamp: now.toISOString()
  }
};

// Define today's planned calendar blocks and top priorities.
// You can replace or connect this with Google Calendar, Notion, or Todoist nodes.
const schedule = [
  {
    time: "09:00 - 09:30",
    title: "Daily Team Standup & Sync",
    type: "Meeting",
    priority: "High"
  },
  {
    time: "10:00 - 12:30",
    title: "Deep Work: n8n Automation Workflows & Learning",
    type: "Focus",
    priority: "High"
  },
  {
    time: "13:00 - 14:00",
    title: "Lunch Break & Recharge",
    type: "Break",
    priority: "Normal"
  },
  {
    time: "14:00 - 16:00",
    title: "Project Tasks, Code Reviews & Bug Fixes",
    type: "Development",
    priority: "Medium"
  },
  {
    time: "16:30 - 17:30",
    title: "Inbox Zero & Documentation Review",
    type: "Admin",
    priority: "Medium"
  },
  {
    time: "17:30 - 18:00",
    title: "Daily Wrap-up & Tomorrow's Plan",
    type: "Planning",
    priority: "Normal"
  }
];

const todos = [
  { task: "Push tested n8n workflow JSON to GitHub repo", status: "Pending" },
  { task: "Review community nodes and API updates", status: "Pending" },
  { task: "Drink 2L water & take regular movement breaks", status: "Pending" }
];

const dailyQuote = "Consistency is what transforms average into excellence.";

return {
  json: {
    schedule,
    todos,
    quote: dailyQuote
  }
};

const dateInfo = $('Prepare Date & Time').first().json;
let weatherInfo = {};
try {
  weatherInfo = $('Fetch Weather (Open-Meteo)').first().json;
} catch (e) {
  weatherInfo = { current_weather: { temperature: 'N/A', windspeed: 'N/A' } };
}
const scheduleData = $('Daily Schedule & Tasks').first().json;

const temp = weatherInfo.current_weather ? `${weatherInfo.current_weather.temperature}°C` : 'N/A';
const wind = weatherInfo.current_weather ? `${weatherInfo.current_weather.windspeed} km/h` : 'N/A';

const scheduleLines = scheduleData.schedule
  .map(item => `• \`${item.time}\` **${item.title}** [${item.priority}]`)
  .join('\n');

const todoLines = scheduleData.todos
  .map(item => `- [ ] ${item.task}`)
  .join('\n');

const briefingText = `📋 **DAILY SCHEDULE & MORNING BRIEFING**\n` +
`━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
`🗓️ **Date:** ${dateInfo.date_formatted}\n` +
`⛅ **Weather:** ${temp} (Wind: ${wind})\n\n` +
`⏰ **TODAY'S SCHEDULE:**\n${scheduleLines}\n\n` +
`🎯 **PRIORITIES & TODOS:**\n${todoLines}\n\n` +
`💡 *"${scheduleData.quote}"*\n` +
`━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`;

return {
  json: {
    subject: `Daily Briefing - ${dateInfo.date_formatted}`,
    briefing_text: briefingText,
    date: dateInfo.date_formatted,
    events_count: scheduleData.schedule.length,
    todos_count: scheduleData.todos.length
  }
};
